import Mathlib

/- The ellipse shown below is defined by the equation
\[PF_1 + PF_2 = d.\]Find $d.$

[asy]
unitsize(0.3 cm);

int i, n = 10;

for (i = -n; i <= n; ++i) {
  draw((i,-n)--(i,n),gray(0.7));
  draw((-n,i)--(n,i),gray(0.7));
}

draw((0,-n)--(0,n));
draw((-n,0)--(n,0));

draw(shift((-1,0))*xscale(7)*yscale(5)*Circle((0,0),1),red);

dot((-1,0));
[/asy] -/
theorem algebra_21510 (d : ℝ) (h : d > 0) (P F1 F2 : ℝ × ℝ)
    (hP : P = (0, 0)) (hF1 : F1 = (-7, 0)) (hF2 : F2 = (7, 0))
    (hP1 : d = Real.sqrt ((P.1 - F1.1)^2 + (P.2 - F1.2)^2) +
      Real.sqrt ((P.1 - F2.1)^2 + (P.2 - F2.2)^2)) :
    d = 14 := by
